'use strict';
const runtime=window.POKESIFT_ROOM;
const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=id=>document.getElementById(id),theme=document.body.dataset.theme,art=runtime?.art||window.CONCEPT_ART||{};
const types={Unclassified:'#aaa',Fighting:'#b68e75',Dark:'#687179',Steel:'#8eaaa8',Ice:'#8dcacc',Fairy:'#cb9bb7',Flying:'#a7b8d2',Bug:'#a5b877',Poison:'#a58cb0',Ground:'#baa17e',Rock:'#aba17d',Ghost:'#8c91ae',Electric:'#d4b847',Fire:'#dc846b',Water:'#79a8c1',Grass:'#8cad65',Psychic:'#ac8aba',Normal:'#b4a58c',Dragon:'#82a4a1'};
const pokemon=runtime?.pokemon||[[25,'Pikachu','Electric',12.5],[6,'Charizard','Fire',284],[7,'Squirtle','Water',8],[1,'Bulbasaur','Grass',6.5],[94,'Gengar','Psychic',68],[133,'Eevee','Normal',9.5],[143,'Snorlax','Normal',47],[149,'Dragonite','Dragon',92],[151,'Mew','Psychic',38],[129,'Magikarp','Water',4.5],[4,'Charmander','Fire',7],[9,'Blastoise','Water',152],[2,'Ivysaur','Grass',null],[5,'Charmeleon','Fire',null],[26,'Raichu','Electric',null],[93,'Haunter','Psychic',null]].map(([id,name,type,value])=>({id,name,type,value}));
const initial=()=>runtime?structuredClone(runtime.cards):[...pokemon.slice(0,12).map((p,i)=>({...p,key:'card-'+i,set:['Base Set','Base Set','Base Set','Base Set','Fossil','Jungle','Jungle','Fossil','Promo','Base Set','Base Set','Base Set'][i],edition:i===1||i===4||i===6||i===7||i===11?'Holofoil':'Original printing'})),{...pokemon[0],key:'pikachu-two',set:'Base Set',edition:'Another favourite',value:8.5},{...pokemon[5],key:'eevee-two',set:'Jungle',edition:'Second copy',value:7.5}];
let cards=initial(),view=theme==='zoo'?'dex':'cards',filter='All',dexFilter='All',page=0,index=0,fanSelectionReset=true,sort='recent',missing=false,pins=new Set(),newFriend=null,dragged=null,swipeX=null,suppressClick=false;
const money=n=>n==null?'Value unknown':new Intl.NumberFormat('en-AU',{style:'currency',currency:'AUD'}).format(n).replace('$','A$');
const hasSpecies=(c,id)=>c.speciesIds?c.speciesIds.includes(id):c.id===id;
const owned=()=>pokemon.filter(p=>cards.some(c=>hasSpecies(c,p.id)));
const valueOfCard=c=>c.valueLabel||money(c.value);
const img=p=>p.image||art['card-'+p.id]||art['pokemon-'+p.id];
const count=id=>cards.filter(c=>hasSpecies(c,id)).length;
function filtered(){let list=cards.filter(c=>(filter==='All'||c.type===filter)&&(!runtime?.query||[c.name,c.set,c.edition].join(' ').toLowerCase().includes(runtime.query)));if(sort==='value')list.sort((a,b)=>(b.value??-1)-(a.value??-1));if(sort==='type')list.sort((a,b)=>a.type.localeCompare(b.type)||a.name.localeCompare(b.name));if(sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name));return list;}
function note(s){$('feedback').textContent=s;$('feedback').hidden=false;clearTimeout(note.timer);note.timer=setTimeout(()=>$('feedback').hidden=true,2500);}
function paintTypes(host,selected,fn){host.replaceChildren();for(const name of ['All',...Object.keys(types).filter(name=>cards.some(c=>c.type===name))]){const b=document.createElement('button');b.textContent=name==='All'?'All types':name;b.className=name===selected?'active':'';b.setAttribute('aria-pressed',String(name===selected));if(name!=='All'){const dot=document.createElement('i');dot.className='type-dot';dot.style.setProperty('--type',types[name]);b.prepend(dot);}b.onclick=()=>fn(name);host.append(b);}}
function render(){
 document.querySelectorAll('[data-option]').forEach(a=>{if(a.dataset.option===theme)a.setAttribute('aria-current','page');});
 document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===view)));
 $('cards-view').hidden=view!=='cards';$('dex-view').hidden=view!=='dex';$('card-count').textContent=cards.length;$('species-count').textContent=owned().length;$('collection-value').textContent=money(cards.reduce((s,c)=>s+(c.value||0),0));
 $('hero-title').innerHTML=theme==='zoo'?'A little world.<br><em>Your kind of wild.</em>':theme==='desk'?'Big finds.<br><em>Good company.</em>':'Good cards.<br><em>Great company.</em>';
 $('hero-copy').textContent=theme==='zoo'?'A home for every Pokémon you’ve collected.':theme==='desk'?'Your favourite cards deserve more than a spreadsheet.':'A little order. A lot of “look what I found”.';
 $('card-heading').textContent=theme==='desk'?'Go on. Have a sift.':'Crack open your binder.';
 $('binder-layout').hidden=theme==='desk';$('desk-layout').hidden=theme!=='desk';if($('sticker-art')&&art['pokemon-25'])$('sticker-art').src=art['pokemon-25'];if(art['pokemon-25'])$('dex-hero-one').src=art['pokemon-25'];if(art['pokemon-151'])$('dex-hero-two').src=art['pokemon-151'];
 paintTypes($('card-filters'),filter,v=>{filter=v;page=0;index=0;fanSelectionReset=true;render();});paintTypes($('dex-filters'),dexFilter,v=>{dexFilter=v;renderDex();});
 renderCards();renderDex();
}
function renderCards(){const list=filtered();$('no-cards').hidden=!!list.length;page=Math.min(page,Math.max(0,Math.ceil(list.length/9)-1));index=Math.min(index,Math.max(0,list.length-1));$('pocket-grid').replaceChildren();
 for(const c of list.slice(page*9,page*9+9)){const pocket=document.createElement('div');pocket.className='pocket';pocket.draggable=true;pocket.innerHTML=`<button class="pocket-button" aria-label="View ${escapeHTML(c.name)}"><div class="card-image"><img src="${escapeHTML(img(c))}" alt="${escapeHTML(c.name)} Pokémon card" draggable="false"></div><span class="pocket-name">${escapeHTML(c.name)}</span><span class="pocket-line"><span class="pocket-price">${money(c.value)}</span><span class="pocket-set">${escapeHTML(c.set)}</span></span></button><button class="pin ${pins.has(c.key)?'pinned':''}" aria-label="${pins.has(c.key)?'Unpin':'Pin'} ${escapeHTML(c.name)}">✦</button>`;
 pocket.querySelector('.pocket-button').onclick=()=>cardDetail(c);pocket.querySelector('.pin').onclick=()=>{pins.has(c.key)?pins.delete(c.key):pins.add(c.key);renderCards();};pocket.ondragstart=()=>dragged=c.key;pocket.ondragover=e=>{e.preventDefault();pocket.classList.add('drop-target');};pocket.ondragleave=()=>pocket.classList.remove('drop-target');pocket.ondrop=e=>{e.preventDefault();const a=cards.findIndex(x=>x.key===dragged),b=cards.findIndex(x=>x.key===c.key);if(a>=0&&b>=0){[cards[a],cards[b]]=[cards[b],cards[a]];sort='custom';$('sort').value=sort;renderCards();}};$('pocket-grid').append(pocket);}
 if(list.length)for(let i=list.slice(page*9,page*9+9).length;i<9;i++){const empty=document.createElement('div');empty.className='empty-pocket';empty.innerHTML='<span>✧</span>Something good<br>will land here.';$('pocket-grid').append(empty);}
 $('page-label').textContent=`PAGE ${page+1} / ${Math.max(1,Math.ceil(list.length/9))}`;$('prev-page').disabled=page===0;$('next-page').disabled=(page+1)*9>=list.length;
 $('card-fan').replaceChildren();for(let offset=-2;offset<=2;offset++){const c=list[index+offset];if(!c)continue;const b=document.createElement('button');b.className='fan-card'+(!offset?' selected':'');b.setAttribute('aria-label',`${escapeHTML(c.name)}, ${money(c.value)}`);b.style.setProperty('--offset',offset*116+'px');b.style.setProperty('--mobile-offset',offset*60+'px');b.style.setProperty('--rotation',offset*10+'deg');b.style.setProperty('--lift',Math.abs(offset)*18+'px');b.style.setProperty('--scale',1-Math.abs(offset)*.08);b.style.setProperty('--opacity',1-Math.abs(offset)*.23);b.style.setProperty('--z',5-Math.abs(offset));b.innerHTML=`<img src="${escapeHTML(img(c))}" alt="${escapeHTML(c.name)}" draggable="false">${!offset?`<span class="fan-price">${money(c.value)}</span>`:''}`;b.onclick=()=>{if(suppressClick)return;if(offset){index+=offset;renderCards();}else cardDetail(c);};$('card-fan').append(b);}
 $('fan-name').textContent=list[index]?.name||'No cards here yet';$('fan-meta').textContent=list[index]?[list[index].type,list[index].set,list[index].edition].join(' · '):'';$('fan-position').textContent=list.length?`${index+1} / ${list.length} CARDS`:'';$('fan-prev').disabled=index===0;$('fan-next').disabled=index>=list.length-1;
 $('thumbnail-rail').replaceChildren();list.forEach((c,i)=>{const b=document.createElement('button');b.className=i===index?'active':'';b.setAttribute('aria-label','Jump to '+c.name);b.innerHTML=`<img src="${escapeHTML(img(c))}" alt="" draggable="false">`;b.onclick=()=>{index=i;renderCards();};$('thumbnail-rail').append(b);});
}
function renderDex(){const list=(missing?pokemon.filter(p=>!count(p.id)):owned()).filter(p=>dexFilter==='All'||p.type===dexFilter);$('owned-count').textContent=owned().length;$('dex-count').textContent=owned().length+' / 151';$('progress-fill').style.width=(owned().length/151*100)+'%';$('collected-tab').setAttribute('aria-pressed',String(!missing));$('missing-tab').setAttribute('aria-pressed',String(missing));paintTypes($('dex-filters'),dexFilter,v=>{dexFilter=v;renderDex();});
 $('species-grid').replaceChildren();list.forEach((p,i)=>{const b=document.createElement('button');b.className='species'+(!count(p.id)?' missing':'')+(p.id===newFriend?' just-found':'');b.setAttribute('aria-label',p.name+', '+(count(p.id)?count(p.id)+' cards':'not yet collected'));b.innerHTML=`<span class="species-number">#${String(p.id).padStart(3,'0')}</span><span class="owned-dot"></span><img src="${escapeHTML(art['pokemon-'+p.id])}" alt="${escapeHTML(p.name)}"><strong>${escapeHTML(p.name)}</strong><small>${count(p.id)?count(p.id)+(count(p.id)===1?' card':' cards'):'Not found yet'}</small>`;b.onclick=()=>speciesDetail(p);$('species-grid').append(b);});
 if(theme==='zoo')renderHabitat(list);
}
function showDetail(html){$('detail-content').innerHTML=html;if(!$('detail').open)$('detail').showModal();}
function cardDetail(c){showDetail(`<div class="detail-grid"><img class="detail-card" src="${escapeHTML(img(c))}" alt="${escapeHTML(c.name)} card"><div><p class="eyebrow">A LITTLE CLOSER</p><h2>${escapeHTML(c.name)}</h2><p>${escapeHTML(c.set)} · ${escapeHTML(c.edition)}<br>${escapeHTML(c.type)} type</p><strong class="detail-value">${money(c.value)}</strong><p>Sample value in Australian dollars.</p><button id="meet-pokemon" class="solid">Meet your ${escapeHTML(c.name)} ↗</button><div class="detail-actions"><button id="move-card">← Move left in binder</button><button id="pin-card">${pins.has(c.key)?'Unpin':'Pin'} favourite ✦</button></div></div></div>`);$('meet-pokemon').onclick=()=>speciesDetail(c);$('pin-card').onclick=()=>{pins.has(c.key)?pins.delete(c.key):pins.add(c.key);renderCards();cardDetail(c);};$('move-card').onclick=()=>{const i=cards.findIndex(x=>x.key===c.key);if(i>0){[cards[i],cards[i-1]]=[cards[i-1],cards[i]];sort='custom';$('sort').value=sort;renderCards();note('Moved one pocket to the left.');}};}
function speciesDetail(p){const copies=cards.filter(c=>hasSpecies(c,p.id));showDetail(`<div class="detail-grid"><img class="detail-art" src="${escapeHTML(art['pokemon-'+p.id])}" alt="${escapeHTML(p.name)}"><div><p class="eyebrow">YOUR POKÉMON · #${String(p.id).padStart(3,'0')}</p><h2>${escapeHTML(p.name)}</h2><p>${escapeHTML(p.type)} · ${copies.length?copies.length+' cards in your collection':'Not in your collection yet'}</p><p>${copies.length?'One Pokémon, a few different ways to love it. Tap a card below to see its printing.':'A little space saved for a future friend.'}</p></div><div class="detail-variants">${copies.map((c,i)=>`<button data-copy="${i}"><img src="${escapeHTML(img(c))}" alt="${escapeHTML(c.name)} ${escapeHTML(c.edition)}">${escapeHTML(c.edition)}<br>${money(c.value)}</button>`).join('')||'<p>No cards of this Pokémon yet.</p>'}</div></div>`);document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=()=>cardDetail(copies[Number(b.dataset.copy)]));}
function moveFan(delta){index=Math.max(0,Math.min(filtered().length-1,index+delta));renderCards();}
$('fan-prev').onclick=()=>moveFan(-1);$('fan-next').onclick=()=>moveFan(1);$('card-fan').onkeydown=e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();moveFan(e.key==='ArrowRight'?1:-1);}};
$('card-fan').onpointerdown=e=>{swipeX=e.clientX;};$('card-fan').onpointerup=e=>{if(swipeX!==null&&Math.abs(e.clientX-swipeX)>35){suppressClick=true;moveFan(e.clientX<swipeX?1:-1);setTimeout(()=>suppressClick=false,50);}swipeX=null;};$('card-fan').onpointercancel=()=>swipeX=null;
$('prev-page').onclick=()=>{page--;renderCards();};$('next-page').onclick=()=>{page++;renderCards();};$('sort').onchange=e=>{sort=e.target.value;page=0;index=0;fanSelectionReset=true;renderCards();};$('shuffle').onclick=()=>{cards.sort(()=>Math.random()-.5);sort='custom';$('sort').value=sort;page=0;index=0;fanSelectionReset=true;renderCards();note('A fresh shuffle. Same favourites.');};
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render();});$('collected-tab').onclick=()=>{missing=false;renderDex();};$('missing-tab').onclick=()=>{missing=true;renderDex();};$('discover').onclick=()=>{const p=pokemon.find(p=>!count(p.id));if(!p){note('Every demo friend is here! Reset to try again.');return;}cards.unshift({...p,key:'new-'+p.id,set:'Demo discovery',edition:'New friend'});newFriend=p.id;missing=false;dexFilter='All';view='dex';render();note('✦ '+p.name+' joined your little crew!');};$('reset-demo').onclick=()=>{cards=initial();pins.clear();newFriend=null;page=0;index=0;fanSelectionReset=true;filter='All';dexFilter='All';sort='recent';missing=false;$('sort').value=sort;render();note('Demo reset. Your real collection is untouched.');};$('close-detail').onclick=()=>$('detail').close();
const labels={binder:'A · The Binder',desk:'B · The Card Room',zoo:'C · The Pokémon Meadow'};
$('choose').onclick=()=>{$('choice-title').textContent=labels[theme];$('choice-copy').textContent=theme==='zoo'?'Pokémon living together in a little world. Tap a friend to open its cards.':theme==='binder'?'Pocket pages, little favourites, and the joy of putting everything in its place.':'A tactile stack to sift through, big artwork, and a bit of after-dark magic.';try{localStorage.setItem('pokesift.prototype.choice',labels[theme]);}catch{}$('choice-dialog').showModal();};$('close-choice').onclick=()=>$('choice-dialog').close();$('copy-choice').onclick=async()=>{const text='I like '+labels[theme]+'. '+$('choice-notes').value;try{await navigator.clipboard.writeText(text);$('choice-status').textContent='Copied. Paste this into our chat when you’re ready.';}catch{$('choice-status').textContent=text;}};
function renderHabitat(list){const scene=$('habitat-creatures');if(!scene)return;scene.replaceChildren();const spots=[[18,57],[72,22],[73,66],[33,32],[19,23],[44,59],[35,75],[79,37],[50,20],[86,78],[58,44],[65,76],[28,48],[61,25],[15,75],[46,40]];list.forEach(p=>{const original=pokemon.findIndex(x=>x.id===p.id),[x,y]=spots[original];const b=document.createElement('button');b.className='habitat-pokemon';b.style.left=x+'%';b.style.top=y+'%';b.style.zIndex=Math.round(y);b.style.setProperty('--delay',(-original*.7)+'s');b.innerHTML=`<img src="${escapeHTML(art['pokemon-'+p.id])}" alt="${escapeHTML(p.name)}"><span>${escapeHTML(p.name)} <small>${count(p.id)} ${count(p.id)===1?'card':'cards'}</small></span>`;b.onclick=()=>speciesDetail(p);scene.append(b);});}
if(!runtime)render();
